import React from "react";

const ageGroups = [
  {
    id: "2-5",
    title: "Little Explorers",
    age: "Ages 2–5",
    color: "from-purple-500 to-purple-700",
    image: "/assets/images/games/bear.png",
    link: "https://www.pbskids.org/games/",
    items: ["Memory", "Matching shapes", "Tap the animal", "Sounds & emotions"],
  },
  {
    id: "6-8",
    title: "Play & Learn",
    age: "Ages 6–8",
    color: "from-blue-500 to-blue-700",
    image: "/assets/images/games/controller.png",
    link: "https://www.funbrain.com/games",
    items: ["Quizzes", "Math games", "Word puzzles", "Hospital games"],
  },
  {
    id: "9-12",
    title: "Smart Games",
    age: "Ages 9–12",
    color: "from-green-500 to-green-700",
    image: "/assets/images/games/rocket.png",
    link: "https://www.coolmathgames.com/",
    items: ["Logic puzzles", "Timed quizzes", "Adventure learning", "Help the doctor"],
  },
  {
    id: "13-18",
    title: "Challenge Zone",
    age: "Ages 13–18",
    color: "from-violet-600 to-violet-800",
    image: "/assets/images/games/brain.png",
    link: "https://www.brainist.com/games",
    items: ["Brain games", "Strategy games", "Quizzes", "Relax games"],
  },
];

export default function Games() {
  return (
    <div className="p-8">
      {/* Яркий заголовок по центру */}
      <h1 className="text-5xl font-extrabold text-center mb-2 bg-clip-text text-transparent bg-gradient-to-r from-purple-500 via-pink-500 to-red-500 drop-shadow-lg">
        🎮 Games
      </h1>
      <p className="text-gray-500 text-center mb-10 text-lg">
        Choose your age group and start playing!
      </p>

      {/* Карточки */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
        {ageGroups.map((group) => (
          <div
            key={group.id}
            className="relative rounded-3xl shadow-xl transform transition hover:scale-105 h-72 flex flex-col justify-end p-6 text-white"
            style={{
              backgroundImage: `url(${group.image})`,
              backgroundSize: "cover",
              backgroundPosition: "center",
            }}
          >
            {/* Полупрозрачная градиентная панель */}
            <div
              className={`absolute inset-0 bg-gradient-to-t ${group.color} bg-opacity-50 rounded-3xl`}
            />

            {/* Контент поверх панели */}
            <div className="relative z-10">
              <h2 className="text-sm mb-1">{group.age}</h2>
              <h3 className="text-2xl font-bold mb-3">{group.title}</h3>

              <ul className="text-sm mb-4 space-y-1">
                {group.items.map((item) => (
                  <li key={item}>• {item}</li>
                ))}
              </ul>

              <a href={group.link} target="_blank" rel="noopener noreferrer">
                <button className="bg-white text-gray-800 hover:bg-gray-200 px-6 py-2 rounded-full font-semibold transition">
                  Play Games
                </button>
              </a>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
